import os,json,subprocess
from pathlib import Path
root=Path("/srv/projects/lowcost-europa")
file=root/".git/info/exclude"
needed=("/data/","/private/","/backups/","/bin/","/www/","/archive/","/.pm2/")
out={"project":"lowcost-europa","status":"BLOCKED","changed":False}
def run(a):
 return subprocess.run(a,capture_output=True,text=True,timeout=12).returncode
def states():
 return {n:subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip() for n in ("ssh","nginx","lowcost-europa","fadego-staging","pink-iptv-backend","pm2-root")}
replaced=False
try:
 if not root.is_dir() or root.is_symlink() or not (root/".git/info").is_dir() or file.is_symlink() or not file.is_file():raise RuntimeError("git_installation_invalid")
 before=file.read_bytes();stat=file.stat()
 for rel in ("data","private","backups","bin","www","archive"):
  if not (root/rel).is_dir():raise RuntimeError("runtime_directory_missing")
 baseline=states()
 text=before.decode("utf8")
 add=[r for r in needed if r not in text.splitlines()]
 updated=text.rstrip()+"\n\n# Canonical VPS project private/runtime directories (do not commit)\n"+"\n".join(add)+"\n"
 archive=root/"archive"/"local-git-protection-20261104"
 archive.mkdir(parents=True,exist_ok=True,mode=0o700)
 back=archive/"info-exclude.before"
 with open(back,"xb") as f:f.write(before);f.flush();os.fsync(f.fileno())
 os.chmod(back,0o600)
 tmp=file.with_name(".exclude.runtime-20261104.tmp")
 with open(tmp,"xb") as f:f.write(updated.encode());f.flush();os.fsync(f.fileno())
 os.chown(tmp,stat.st_uid,stat.st_gid);os.chmod(tmp,stat.st_mode&0o777)
 if file.read_bytes()!=before:raise RuntimeError("concurrent_git_exclude_change")
 os.replace(tmp,file);replaced=True
 checked={}
 for rel in ("data/","private/","backups/","bin/","www/","archive/"):
  cmd=["git","-c",f"safe.directory={root}","-C",str(root),"check-ignore","-q","--no-index",rel]
  checked[rel]=run(cmd)==0
 if not all(checked.values()) or states()!=baseline:raise RuntimeError("git_exclusion_or_service_postcheck_failed")
 out.update(status="GIT_EXCLUDE_VERIFIED",changed=True,protected_directories=list(checked),backup_in_project=True,services_unchanged=True)
except Exception as e:
 out["reason"]=str(e)[:160]
 if replaced:
  try:
   tmp=file.with_name(".exclude.runtime-revert.tmp")
   with open(tmp,"xb") as f:f.write(before);f.flush();os.fsync(f.fileno())
   os.chown(tmp,stat.st_uid,stat.st_gid);os.chmod(tmp,stat.st_mode&0o777);os.replace(tmp,file)
   out["rollback"]="RESTORED"
  except Exception:out["rollback"]="INCOMPLETE"
print(json.dumps(out,sort_keys=True))
if out["status"]!="GIT_EXCLUDE_VERIFIED":raise SystemExit(3)
